jsonTools.init:
function init(eli) {
  // 2026-05-25: register ai_image_model setting. Lives in eli_settings
  // (not the kernel, not admin_fleet) because:
  //   - Every user has eli_settings → registration runs for everyone
  //   - admin_fleet is admin-only → can't be the home (colleagues miss it)
  //   - Image-gen defaults stay in this tool (not the kernel) per the
  //     "kernel has only text fallbacks" decision (2026-05-25)
  // adminPushable so admins can broadcast a specific image model with
  // force/soft layer the same way they push ai_model. apply callback
  // could be added later to update an internal _config.imageModel cache
  // when eli.ai gets generateImage support.
  try {
    if (eli.settings && typeof eli.settings.register === "function") {
      eli.settings.register("ai_image_model", {
        // 2026-05-25: default to the first BUILTIN_IMAGE_MODEL so tools
        // that call eli.ai.generateImage / editImage work out of the box
        // without forcing the user to configure Settings first. Admin
        // can still force-push a different one via admin_fleet.
        default: "gemini-3.1-flash-image-preview",
        type: "string",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "aiImageModel" },
        adminPushable: true,
        describe: "Gemini model used for image generation",
      });
    }
  } catch (_e) {}
  // [AI-OFF] Settings > Global "Turn off AI": every eli.ai call is refused while on.
  // Tool-side for now (eli_settings is boot tier); belongs in the kernel's ai _preflight in the next kernel batch.
  try {
    if (eli.settings && typeof eli.settings.register === "function") {
      eli.settings.register("ai_off", {
        default: false,
        type: "boolean",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "aiOff" },
        adminPushable: true,
        describe: "Turn off AI: ELI makes no AI calls",
      });
      // body.eli-ai-off while on: tools grey out their AI-only buttons with CSS alone.
      var _aiOffClass = function (on) { if (typeof document !== "undefined" && document.body) document.body.classList.toggle("eli-ai-off", on === true); };
      _aiOffClass(true);

    }
    var _ai = eli.ai;
    if (_ai && !_ai._aiOffWrapped) {
      ["complete", "completeJSON", "completeStream", "generateImage", "editImage"].forEach(function (name) {
        var orig = _ai[name];
        if (typeof orig !== "function") return;
        _ai[name] = function () {
          if (true) {   // ELI for Harvey: AI is always off
            var E = eli.errors && eli.errors.ValidationError;
            var msg = "ELI for Harvey has no AI.";
            return Promise.reject(E ? new E(msg, { meta: { hint: "ai_off" } }) : new Error(msg));
          }
          return orig.apply(_ai, arguments);
        };
      });
      _ai._aiOffWrapped = true;
    }
  } catch (_e) {}
  // [/AI-OFF]
  // Kernel-skew-safe aliases: pass-through if kernel pre-eli.events.
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // Storage size warning — moved from kernel §17.3 (2026-05-12).
  // Fires once on tool init. Emits log event + bus event so any UI
  // listener can surface a "running low on storage" banner. Same
  // semantics as v3 boot — just delayed until eli_settings preload.
  (function _checkStorageUsage() {
    if (!eli.storage || !eli.storage.estimate) return;
    eli.storage.estimate().then(function (e) {
      if (!e || !e.percent) return;
      if (e.percent >= 80) {
        eli.log.event("storage", "high_usage", e);
        try { eli.bus.emit("storage:high_usage", e); } catch (err) {}
      }
    });
  })();
  // ── Helpers ─────────────────────────────────────────────────────────
  function _section(panel, title) {
    var h = document.createElement("div");
    h.className = "_eli3_settings_section_head";
    h.textContent = title;
    panel.appendChild(h);
    var box = document.createElement("div");
    box.className = "_eli3_settings_section_body";
    panel.appendChild(box);
    return box;
  }
  function _row(label, control, hint) {
    var r = document.createElement("div");
    r.className = "_eli3_settings_row";
    var main = document.createElement("div");
    main.className = "_eli3_settings_row_main";
    var l = document.createElement("div");
    l.className = "_eli3_settings_label";
    l.textContent = label;
    main.appendChild(l);
    var c = document.createElement("div");
    c.className = "_eli3_settings_control";
    if (control) c.appendChild(control);
    main.appendChild(c);
    r.appendChild(main);
    if (hint) {
      var h = document.createElement("div");
      h.className = "_eli3_settings_hint";
      h.textContent = hint;
      r.appendChild(h);
    }
    return r;
  }
  function _toggle(checked, onchange, labelText) {
    var wrap = document.createElement("label");
    wrap.className = "_eli3_settings_toggle";
    var cb = document.createElement("input");
    cb.type = "checkbox";
    cb.checked = !!checked;
    cb.onchange = function () { onchange(cb.checked, cb); };
    wrap.appendChild(cb);
    var slider = document.createElement("span");
    slider.className = "_eli3_settings_toggle_slider";
    wrap.appendChild(slider);
    if (labelText) {
      var t = document.createElement("span");
      t.className = "_eli3_settings_toggle_label";
      t.textContent = labelText;
      wrap.appendChild(t);
    }
    return wrap;
  }
  function _readUserSettings() {
    try {
      var raw = eli.compat.lsGet("eli_user_settings");
      return raw ? JSON.parse(raw) : {};
    } catch (e) { return {}; }
  }
  function _writeUserSettings(s) {
    try { eli.compat.lsSet("eli_user_settings", JSON.stringify(s)); }
    catch (e) { /* noop */ }
  }

  // ── Shared section builders (used by Global + Interface) ──────────

  // AI Model selector + inline Edit panel (matches v2 lines 5945-6018).
  // v2 stored the user's custom model list inside `userSettings.modelList`
  // (part of the existing `eli_user_settings` blob), NOT a separate key.
  // Earlier v3 builds wrongly added a new `eli_custom_models` localStorage
  // key + a brief IDB-migration detour — both fixed 2026-05-16. We now use
  // v2's actual storage path: read/write `eli_user_settings.modelList`.
  // Sweep the bad key on first read so installs that picked up the wrong
  // builds don't keep stale data sitting around.
  // 2026-05-25: aligned with kernel cold-start defaults (DEFAULT_MODEL +
  // BACKUP_DEFAULT_MODEL). When the user has no custom modelList pref,
  // the picker shows these. Admin's "AI Models Manager" can grow the
  // ai_model_list beyond these via discovery; those additions show up
  // in the picker automatically via _allModels().
  var BUILTIN_MODELS = [
    "gemini-flash-lite-latest",
    "gemini-flash-latest",
  ];
  // 2026-05-25: built-in image models. Kept here (not in kernel) per
  // decision that image gen defaults live in the tool, not the kernel.
  // Picker shows these + any image-capable entries from ai_model_list
  // (admin's curated list). User picks one → eli.settings.set persists
  // to ai_image_model.
  var BUILTIN_IMAGE_MODELS = [
    "gemini-3.1-flash-image-preview",
    "gemini-2.5-flash-image",
  ];
  var _badKeyMigrated = false;
  function _migrateBadKey() {
    if (_badKeyMigrated) return;
    _badKeyMigrated = true;
    try {
      var raw = eli.compat.lsGet("eli_custom_models");
      if (raw) {
        var arr = JSON.parse(raw);
        if (Array.isArray(arr) && arr.length) {
          var s = _readUserSettings();
          var existing = Array.isArray(s.modelList) ? s.modelList : [];
          arr.forEach(function (m) {
            if (m && existing.indexOf(m) === -1) existing.push(m);
          });
          s.modelList = existing;
          _writeUserSettings(s);
        }
        eli.compat.lsRemove("eli_custom_models");
      }
    } catch (e) {}
    // Also clear the brief IDB attempt if it landed for anyone.
    try {
      if (eli.storage && eli.storage.delete) {
        eli.storage.delete("config", "custom_models").catch(function () {});
      }
    } catch (e) {}
  }
  function _readCustomModels() {
    _migrateBadKey();
    var s = _readUserSettings();
    return Array.isArray(s.modelList) ? s.modelList : [];
  }
  function _writeCustomModels(arr) {
    var s = _readUserSettings();
    s.modelList = Array.isArray(arr) ? arr : [];
    _writeUserSettings(s);
  }
  function _allModels() {
    var custom = _readCustomModels();
    var current = eli.ai.getModel();
    var seen = {};
    var out = [];
    custom.concat(BUILTIN_MODELS).concat([current]).forEach(function (m) {
      if (m && !seen[m]) { seen[m] = true; out.push(m); }
    });
    return out;
  }
  // 2026-05-25: image model picker pool = BUILTIN_IMAGE_MODELS +
  // any image-capable entries (/image/i) from ai_model_list. Admin's
  // discovery flow writes to ai_model_list, so newly-discovered image
  // models surface here automatically. Deduped, built-ins first so the
  // recommended choice sits at the top.
  function _allImageModels() {
    var seen = {};
    var out = [];
    BUILTIN_IMAGE_MODELS.forEach(function (m) {
      if (m && !seen[m]) { seen[m] = true; out.push(m); }
    });
    try {
      var fromList = (eli.settings && typeof eli.settings.get === "function")
        ? (eli.settings.get("ai_model_list") || [])
        : [];
      fromList.forEach(function (m) {
        if (m && /image/i.test(m) && !seen[m]) { seen[m] = true; out.push(m); }
      });
    } catch (_e) {}
    return out;
  }
  function _inlineRow(controlEl, btnEl) {
    var r = document.createElement("div");
    r.className = "_eli3_settings_inline_row";
    if (controlEl) r.appendChild(controlEl);
    if (btnEl) r.appendChild(btnEl);
    return r;
  }

  // 2026-05-25: admin-password gate for AI model editors.
  // - Session-only unlock (re-prompt on snippet reload)
  // - Compares against localStorage `eli_admin_password` set by admin
  // - Colleagues without password set on their machine cannot unlock
  // - Falls back to native prompt() if eli.ui.prompt isn't loaded yet
  var _aiEditorUnlocked = false;
  function _hasAdminPassword() {
    try {
      var p = eli.compat && eli.compat.lsGet && eli.compat.lsGet("eli_admin_password");
      return !!(p && String(p).length > 0);
    } catch (_e) { return false; }
  }
  function _requireAdminPassword(actionLabel) {
    if (_aiEditorUnlocked) return Promise.resolve(true);
    if (!_hasAdminPassword()) {
      if (typeof showToast === "function") {
        showToast("🔒 " + actionLabel + " — admin-only (no admin password set on this machine)", "warn");
      }
      return Promise.resolve(false);
    }
    var stored = eli.compat.lsGet("eli_admin_password");
    return new Promise(function (resolve) {
      if (eli.ui && typeof eli.ui.prompt === "function") {
        eli.ui.prompt({
          title: "🔒 Admin password required",
          message: actionLabel + ". Enter admin password to unlock for this session.",
          placeholder: "Admin password",
          // 2026-05-25: masked input — kernel prompt supports inputType but
          // defaults to "text" so the call site has to opt in for masking.
          inputType: "password",
          validate: function (val) {
            return val === stored ? null : "Incorrect password";
          },
        }).then(function (val) {
          if (val === null || val === undefined) { resolve(false); return; }
          _aiEditorUnlocked = true;
          if (typeof showToast === "function") showToast("🔓 AI model editor unlocked for this session", "ok");
          resolve(true);
        }).catch(function () { resolve(false); });
      } else {
        var entered = window.prompt(actionLabel + " — admin password:");
        if (entered === stored) {
          _aiEditorUnlocked = true;
          resolve(true);
        } else {
          if (entered != null && typeof showToast === "function") showToast("Incorrect password", "err");
          resolve(false);
        }
      }
    });
  }

  // ─── [THINK-MODE] ───────────────────────────────────────────────────
  // Thinking depth for every AI call. Two states only: what ELI picked per
  // tool, or your own numbers. A slider rather than named tiers because the
  // useful move when something feels slow is "try less" — and how much less
  // is a judgement, not a menu.
  // Kernel resolves this in _buildBody; this is only the UI.
  // TO REMOVE: delete this function and its call in the panel builder.
  var _THINK_STEPS = [0, 256, 512, 1024, 2048, 4096, 8192];
  // Tools that actually make AI calls, most-used first. Anything absent
  // follows the global slider.
  // [id, name, what ELI ships for it] — the third column is display only,
  // mirroring values that live in each tool. Update it when a tool retunes.
  var _THINK_TOOLS = [
    ["error_review", "Error Review", "0 / 1024 / 4096 by sensitivity"],
    ["review_redlines", "Review Redlines", "512, 1024 adjudicating"],
    ["legal_risks", "Legal Risks", "1024"],
    ["build_draft", "Build Draft", "0 for field lookups"],
    ["polish", "Polish", "256-512"],
    ["ask_eli", "Ask ELI", "model decides"],
    ["compare", "Compare", "model decides"],
    ["final_review", "Final Review", "model decides"],
    ["email_helper", "Email Helper", "model decides"],
  ];
  // "Off (0)" rather than "Off" — the number IS zero, and leaving that
  // implicit made people ask whether Off was a separate state.
  function _thinkLabel(v) { return Number(v) === 0 ? "Off (0)" : String(v); }

  // The slider is a token budget, which means nothing on its own — say what
  // each end of it actually buys.
  function _thinkLegend() {
    var el = document.createElement("div");
    el.className = "_eli3_think_legend";
    el.innerHTML =
      "<b>Auto</b> — no override; follow the mode above.<br>" +
      "<b>Off (0)</b> — zero thinking tokens. The model answers immediately: " +
      "fastest, cheapest, least careful.<br>" +
      "<b>8192</b> — the most thinking allowed. Slowest.<br>" +
      "Depth only buys accuracy on judgement calls (is this clause risky? is " +
      "this term defined?). On lookups and short rewrites it costs time and " +
      "changes nothing.";
    return el;
  }

  function _buildThinkingSection(panel) {
    if (!eli.settings || typeof eli.settings.get !== "function") return;
    var box = _section(panel, "🧠 Thinking Depth");

    function _get(k, d) {
      try { var v = eli.settings.get(k); return (v == null || v === "") ? d : v; }
      catch (e) { return d; }
    }
    var mode = String(_get("ai_thinking_mode", "recommended"));
    var perTool = _get("ai_thinking_per_tool", {}) || {};
    if (typeof perTool !== "object") perTool = {};

    var sel = document.createElement("select");
    sel.className = "_eli3_input";
    [["recommended", "ELI recommends (per tool)"], ["custom", "Custom"]].forEach(function (o) {
      var el = document.createElement("option");
      el.value = o[0]; el.textContent = o[1];
      if (o[0] === mode) el.selected = true;
      sel.appendChild(el);
    });
    box.appendChild(_row("Thinking depth", sel,
      "Recommended uses the budget each tool was tuned with. Custom applies one number everywhere. A per-tool value below beats both."));

    // auto === true prepends an "Auto" position meaning "no override here".
    // Returns the parts rather than a finished row: the chip belongs on the
    // label line and the track on its own full-width line below, so every
    // slider starts and ends at the same x. Laid out inline, the track's
    // start moved with the length of the tool's name.
    function _slider(initial, onPick, auto) {
      var steps = auto ? [null].concat(_THINK_STEPS) : _THINK_STEPS;
      var r = document.createElement("input");
      r.type = "range";
      r.className = "_eli3_think_slider";
      r.min = "0"; r.max = String(steps.length - 1); r.step = "1";
      var idx = (initial == null) ? (auto ? 0 : -1) : steps.indexOf(Number(initial));
      r.value = String(idx === -1 ? (auto ? 0 : 2) : idx);
      var out = document.createElement("span");
      function paint() {
        var v = steps[Number(r.value)];
        out.textContent = (v == null) ? "Auto" : _thinkLabel(v);
        // Gold marks Auto only — every explicit number, 0 included, is a
        // neutral chip. "Off (0)" says what it is; colour-coding it red
        // would read as a warning it isn't.
        out.className = "_eli3_think_val" + (v == null ? " _is_auto" : "");
        r.title = out.textContent;
      }
      paint();
      r.oninput = paint;
      r.onchange = function () { onPick(steps[Number(r.value)]); };
      return { input: r, chip: out };
    }

    function _thinkRow(name, parts, hint) {
      var row = document.createElement("div");
      row.className = "_eli3_settings_row _eli3_think_r";
      var head = document.createElement("div");
      head.className = "_eli3_think_head";
      var l = document.createElement("div");
      l.className = "_eli3_settings_label";
      l.textContent = name;
      head.appendChild(l);
      head.appendChild(parts.chip);
      row.appendChild(head);
      row.appendChild(parts.input);
      if (hint) {
        var h = document.createElement("div");
        h.className = "_eli3_settings_hint";
        h.textContent = hint;
        row.appendChild(h);
      }
      return row;
    }

    // One number for everything — only meaningful in Custom, since
    // Recommended has no single value to show.
    var custom = document.createElement("div");
    custom.style.display = mode === "custom" ? "" : "none";
    custom.appendChild(_thinkRow("All tools",
      _slider(_get("ai_thinking_custom", 512), function (v) {
        eli.settings.set("ai_thinking_custom", v, { layer: "user" });
        showToast("All tools: " + _thinkLabel(v), "ok");
      }),
      "One number for every tool. A per-tool value below still wins."));
    box.appendChild(custom);

    // Per-tool values apply in BOTH modes — that is how one tool's
    // recommended depth gets retuned without switching everything to Custom.
    var head = document.createElement("div");
    head.className = "_eli3_settings_section_head";
    head.textContent = "Per tool";
    head.style.cssText = "margin-top:10px;";
    box.appendChild(head);

    box.appendChild(_thinkLegend());

    _THINK_TOOLS.forEach(function (t) {
      var id = t[0], name = t[1], ships = t[2];
      var sl = _slider(perTool[id] == null ? null : perTool[id], function (v) {
        if (v == null) delete perTool[id];
        else perTool[id] = v;
        eli.settings.set("ai_thinking_per_tool", perTool, { layer: "user" });
        showToast(name + ": " + (v == null ? "Auto" : _thinkLabel(v)), "ok");
      }, true);
      box.appendChild(_thinkRow(name, sl, "ELI's own: " + ships));
    });

    sel.onchange = function () {
      eli.settings.set("ai_thinking_mode", sel.value, { layer: "user" });
      custom.style.display = sel.value === "custom" ? "" : "none";
      showToast(sel.value === "custom"
        ? "Custom thinking depth in effect."
        : "Back to ELI's per-tool defaults.", "ok");
    };
  }
  // ─── [/THINK-MODE] ──────────────────────────────────────────────────

  function _buildAiModelSection(panel) {
    var box = _section(panel, "🤖 AI Model");
    var modelSel = document.createElement("select");
    modelSel.className = "_eli3_input";
    function _populate() {
      modelSel.innerHTML = "";
      var current = eli.ai.getModel();
      _allModels().forEach(function (m) {
        var o = document.createElement("option");
        o.value = m; o.textContent = m;
        if (m === current) o.selected = true;
        modelSel.appendChild(o);
      });
    }
    _populate();
    modelSel.onchange = function () {
      // 2026-05-25: write through eli.settings so the pick persists
      // across reloads. The old call to eli.ai.setModel only updated
      // _config.model in memory — picker change worked for the session
      // but reverted on snippet reload. The kernel's setModel was
      // patched in the same commit to delegate similarly; this site
      // still calls settings directly so older kernels also benefit.
      if (eli.settings && typeof eli.settings.set === "function") {
        eli.settings.set("ai_model", modelSel.value, { layer: "user" });
      } else if (eli.ai && typeof eli.ai.setModel === "function") {
        eli.ai.setModel(modelSel.value); // pre-settings fallback
      }
      showToast("Model: " + modelSel.value, "ok");
    };
    var editToggle = document.createElement("button");
    editToggle.type = "button";
    editToggle.className = "_eli3_settings_link_btn";
    editToggle.textContent = "✏️ Edit";
    box.appendChild(_inlineRow(modelSel, editToggle));

    var editPanel = document.createElement("div");
    editPanel.className = "_eli3_settings_inline_panel";
    editPanel.style.display = "none";
    var editList = document.createElement("div");
    editPanel.appendChild(editList);
    var addInput = document.createElement("input");
    addInput.type = "text";
    addInput.className = "_eli3_input";
    addInput.placeholder = "e.g. gemini-2.5-pro-preview";
    var addBtn = eliButton({
      label: "+ Add",
      onclick: function () {
        var name = (addInput.value || "").trim();
        if (!name) return;
        var custom = _readCustomModels();
        if (custom.indexOf(name) !== -1) { showToast("Already in list.", "warn"); return; }
        custom.push(name);
        _writeCustomModels(custom);
        addInput.value = "";
        _renderEditList();
        _populate();
      },
    });
    editPanel.appendChild(_inlineRow(addInput, addBtn));
    box.appendChild(editPanel);

    function _renderEditList() {
      editList.innerHTML = "";
      var custom = _readCustomModels();
      if (!custom.length) {
        var hint = document.createElement("div");
        hint.className = "_eli3_settings_hint";
        hint.textContent = "Built-ins: " + BUILTIN_MODELS.join(", ");
        editList.appendChild(hint);
        return;
      }
      custom.forEach(function (m, i) {
        var row = document.createElement("div");
        row.className = "_eli3_settings_chip_row";
        // 2026-05-23: model name is now editable in place. Type a new
        // name → blur (or press Enter) to save. Empty value → ignored
        // (use the ✕ button to remove).
        var nameInput = document.createElement("input");
        nameInput.type = "text";
        nameInput.value = m;
        nameInput.className = "_eli3_input";
        nameInput.style.cssText = "flex:1;background:transparent;border:1px solid transparent;padding:2px 6px;font:13px/1.3 'Inter',sans-serif;";
        nameInput.title = "Edit name + press Enter or click out to save";
        nameInput.onfocus = function () { nameInput.style.border = "1px solid #1565c0"; nameInput.style.background = "#fff"; };
        nameInput.onkeydown = function (e) {
          if (e.key === "Enter") { e.preventDefault(); nameInput.blur(); }
          if (e.key === "Escape") { nameInput.value = m; nameInput.blur(); }
        };
        nameInput.onblur = function () {
          nameInput.style.border = "1px solid transparent";
          nameInput.style.background = "transparent";
          var newName = (nameInput.value || "").trim();
          var arr = _readCustomModels();
          if (!newName || newName === arr[i]) {
            nameInput.value = arr[i] || m; // revert if blank or unchanged
            return;
          }
          // Reject if name collides with another entry (custom or built-in)
          if (arr.indexOf(newName) !== -1 || BUILTIN_MODELS.indexOf(newName) !== -1) {
            showToast("\"" + newName + "\" already in list — pick a different name.", "warn");
            nameInput.value = arr[i] || m;
            return;
          }
          var wasCurrent = eli.ai.getModel() === arr[i];
          arr[i] = newName;
          _writeCustomModels(arr);
          showToast("Renamed to " + newName, "ok");
          // If the renamed model was the currently-selected one, point
          // the AI provider at the new name so subsequent calls work.
          if (wasCurrent) {
            try { eli.ai.setModel(newName); } catch (_e) {}
          }
          _renderEditList();
          _populate();
        };
        var delBtn = document.createElement("button");
        delBtn.className = "_eli3_settings_chip_del";
        delBtn.textContent = "✕";
        delBtn.title = "Remove from list";
        delBtn.onclick = function () {
          var arr = _readCustomModels();
          arr.splice(i, 1);
          _writeCustomModels(arr);
          _renderEditList();
          _populate();
        };
        row.appendChild(nameInput);
        row.appendChild(delBtn);
        editList.appendChild(row);
      });
    }
    editToggle.onclick = function () {
      var open = editPanel.style.display !== "none";
      if (open) {
        // Closing — no password needed
        editPanel.style.display = "none";
        editToggle.textContent = "🔒 ✏️ Edit";
        return;
      }
      // Opening — require admin password (session unlock)
      _requireAdminPassword("Edit AI text model list").then(function (ok) {
        if (!ok) return;
        editPanel.style.display = "block";
        editToggle.textContent = "✕ Done";
        _renderEditList();
      });
    };
    // Show 🔒 by default until unlocked, so colleagues see it's gated.
    editToggle.textContent = "🔒 ✏️ Edit";
  }

  // 2026-05-25: Image generation model picker + editor. Mirror of the
  // text model section. Picker shows BUILTIN_IMAGE_MODELS + any
  // image-capable entries (/image/i) from ai_model_list. Editor is
  // password-gated (same admin password as the text editor) and lets
  // admin add / remove / rename custom image models. Custom entries
  // share storage with the text editor (ai_model_list / s.modelList);
  // image picker filters at display time so they only show where
