  function _buildAiImageModelSection(panel) {
    var box = _section(panel, "🖼 AI Image Model");
    var sel = document.createElement("select");
    sel.className = "_eli3_input";
    function _populate() {
      sel.innerHTML = "";
      var current = "";
      try {
        if (eli.settings && typeof eli.settings.get === "function") {
          current = eli.settings.get("ai_image_model") || "";
        }
      } catch (_e) {}
      // Empty option for "disabled / not configured"
      var noneOpt = document.createElement("option");
      noneOpt.value = "";
      noneOpt.textContent = "— none (image gen disabled) —";
      if (!current) noneOpt.selected = true;
      sel.appendChild(noneOpt);
      _allImageModels().forEach(function (m) {
        var o = document.createElement("option");
        o.value = m; o.textContent = m;
        if (m === current) o.selected = true;
        sel.appendChild(o);
      });
    }
    _populate();
    sel.onchange = function () {
      if (eli.settings && typeof eli.settings.set === "function") {
        eli.settings.set("ai_image_model", sel.value || null, { layer: "user" });
        showToast("Image model: " + (sel.value || "(none)"), "ok");
      } else {
        showToast("eli.settings not loaded — can't persist", "warn");
      }
    };

    // ✏️ Edit button (admin password gated)
    var editToggle = document.createElement("button");
    editToggle.type = "button";
    editToggle.className = "_eli3_settings_link_btn";
    editToggle.textContent = "🔒 ✏️ Edit";
    box.appendChild(_inlineRow(sel, editToggle));

    // Edit panel (hidden until unlocked)
    var editPanel = document.createElement("div");
    editPanel.className = "_eli3_settings_inline_panel";
    editPanel.style.display = "none";
    var editList = document.createElement("div");
    editPanel.appendChild(editList);
    var addInput = document.createElement("input");
    addInput.type = "text";
    addInput.className = "_eli3_input";
    addInput.placeholder = "e.g. gemini-3.1-flash-image-preview";
    var addBtn = eliButton({
      label: "+ Add",
      onclick: function () {
        var name = (addInput.value || "").trim();
        if (!name) return;
        var custom = _readCustomModels();
        if (custom.indexOf(name) !== -1 || BUILTIN_IMAGE_MODELS.indexOf(name) !== -1) {
          showToast("Already in list.", "warn"); return;
        }
        custom.push(name);
        _writeCustomModels(custom);
        addInput.value = "";
        _renderEditList();
        _populate();
      },
    });
    editPanel.appendChild(_inlineRow(addInput, addBtn));
    box.appendChild(editPanel);

    function _renderEditList() {
      editList.innerHTML = "";
      // Show custom entries that match /image/i (image-named additions).
      var custom = _readCustomModels().filter(function (m) { return /image/i.test(m); });
      if (!custom.length) {
        var hint = document.createElement("div");
        hint.className = "_eli3_settings_hint";
        hint.textContent = "Built-ins: " + BUILTIN_IMAGE_MODELS.join(", ") +
          ". Type any model name with \"image\" in it to add a custom one.";
        editList.appendChild(hint);
        return;
      }
      custom.forEach(function (m) {
        var row = document.createElement("div");
        row.className = "_eli3_settings_chip_row";
        var label = document.createElement("span");
        label.style.cssText = "flex:1;font:600 12px ui-monospace,Consolas,monospace;color:#0f172a;";
        label.textContent = m;
        var delBtn = document.createElement("button");
        delBtn.type = "button";
        delBtn.textContent = "✕";
        delBtn.style.cssText = "padding:4px 8px;font:700 12px Inter,sans-serif;background:#fee2e2;border:1px solid #fecaca;color:#b91c1c;cursor:pointer;";
        delBtn.onclick = function () {
          var arr = _readCustomModels();
          var idx = arr.indexOf(m);
          if (idx !== -1) arr.splice(idx, 1);
          _writeCustomModels(arr);
          // Clear ai_image_model if it pointed at this entry.
          try {
            if (eli.settings && eli.settings.get && eli.settings.get("ai_image_model") === m) {
              eli.settings.set("ai_image_model", null, { layer: "user" });
            }
          } catch (_) {}
          _renderEditList();
          _populate();
        };
        row.appendChild(label);
        row.appendChild(delBtn);
        editList.appendChild(row);
      });
    }

    editToggle.onclick = function () {
      var open = editPanel.style.display !== "none";
      if (open) {
        editPanel.style.display = "none";
        editToggle.textContent = "🔒 ✏️ Edit";
        return;
      }
      _requireAdminPassword("Edit AI image model list").then(function (ok) {
        if (!ok) return;
        editPanel.style.display = "block";
        editToggle.textContent = "✕ Done";
        _renderEditList();
      });
    };

    var hint = document.createElement("div");
    hint.className = "_eli3_settings_hint";
    hint.style.marginTop = "6px";
    hint.textContent = "Built-ins: " + BUILTIN_IMAGE_MODELS.join(", ") +
      ". Additional models added via admin (Discover) appear here automatically.";
    box.appendChild(hint);
  }

  // Combined: update-check frequency + manual install share a row.
  // ─── [CORE-OS] ──────────────────────────────────────────────────────
  // Somewhere to LOOK. The kernel_check tool surfaces itself when you're
  // behind, but "am I current?" had no answer short of the console —
  // silence and "no marker published" looked identical from the outside.
  // TO REMOVE: delete this function and its call in _buildGlobalDetail.
  function _buildCoreOsSection(panel) {
    var box = _section(panel, "⚡ ELI OS");

    var running = (window.eli && eli.kernelVersion) || "unknown";
    var stamped = /^v3-\d{4}-\d{2}-\d{2}-(?:\d{4}-)?[0-9a-f]{7}$/.test(String(running));

    // The Script and Style panes are pasted separately, so they can drift.
    // make_deploy stamps the same version into the CSS as a custom property;
    // reading it back is the only way to tell whether the stylesheet on this
    // install actually belongs to the kernel running beside it.
    // "" means a stylesheet from before stamping — unknown, not stale.
    var styleVersion = "";
    try {
      styleVersion = String(getComputedStyle(document.documentElement)
        .getPropertyValue("--eli-build") || "").trim().replace(/^["']|["']$/g, "");
    } catch (e) { styleVersion = ""; }
    var styleMismatch = !!(styleVersion && stamped && styleVersion !== running);

    var pill = document.createElement("span");
    function setPill(text, bg, fg) {
      pill.textContent = text;
      pill.style.cssText = "display:inline-block;padding:4px 10px;background:" + bg +
        ";color:" + (fg || "#fff") + ";font:800 9.5px/1.1 Inter,sans-serif;" +
        "letter-spacing:.08em;text-transform:uppercase;";
    }
    setPill("Checking…", "#64748b");

    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "_eli3_settings_link_btn";
    btn.textContent = "Check now";

    var ctl = document.createElement("div");
    ctl.style.cssText = "display:flex;align-items:center;gap:9px;";
    ctl.appendChild(pill);
    ctl.appendChild(btn);

    box.appendChild(_row("Status", ctl,
      "Running " + running +
      (stamped ? "" : " — an unstamped build; this string can be older than the code.")));

    // Only worth a line when it says something: a matching stylesheet is the
    // expected case and doesn't need announcing.
    if (styleMismatch || (!styleVersion && stamped)) {
      var warn = document.createElement("div");
      warn.className = "_eli3_settings_hint";
      warn.style.cssText = "border-left:3px solid #b45309;background:#fffbeb;" +
        "color:#7c2d12;padding:8px 10px;margin:6px 0 0;";
      warn.textContent = styleMismatch
        ? "Stylesheet is from a different build (" + styleVersion + "). Paste " +
          "taskpane_v3.deploy.css into Script Lab's Style pane as well."
        : "Stylesheet predates build stamping, so it can't be checked. Pasting " +
          "the current .deploy.css into the Style pane settles it.";
      box.appendChild(warn);
    }

    function refresh() {
      setPill("Checking…", "#64748b");
      var p;
      try { p = eli.dispatch("kernel_check", "latest", true); }
      catch (e) { p = null; }
      if (!p || typeof p.then !== "function") {
        setPill("Unavailable", "#64748b");
        btn.textContent = "Check now";
        return;
      }
      p.then(function (latest) {
        if (!latest) { setPill("None published", "#64748b"); return; }
        var v = { state: "unknown" };
        try { v = eli.dispatch("kernel_check", "verdict", running, latest) || v; }
        catch (e) { /* fall through to unknown */ }
        if (v.state === "current") setPill("Up to date", "#15803d");
        else if (v.state === "behind") setPill("Update needed", "#b45309");
        else if (v.state === "ahead") setPill("Ahead of published", "#6d28d9");
        else setPill("Unknown", "#64748b");
        // Behind is the one state with something to do about it.
        if (v.state === "behind") {
          btn.textContent = "How to update";
          btn.onclick = function () {
            try { eli.dispatch("kernel_check", "open"); } catch (e) {}
          };
        } else {
          btn.textContent = "Check now";
          btn.onclick = refresh;
        }
      }).catch(function () { setPill("Can't reach CDN", "#64748b"); });
    }
    btn.onclick = refresh;
    refresh();
  }
  // ─── [/CORE-OS] ─────────────────────────────────────────────────────

  function _buildMaintenanceSection(panel) {
