      var wRow = document.createElement("div");
      wRow.style.cssText = "display:flex;align-items:center;gap:10px;flex-wrap:wrap";
      wRow.appendChild(eliButton({
        label: "🧩 Manage Widgets",
        variant: "secondary",
        onclick: function () {
          var r = null;
          try { r = eli.dispatch("widgets", "openManager"); } catch (_e) {}
          if (r === undefined && typeof showToast === "function") {
            showToast("Widgets tool not loaded yet — try again in a moment.", "warn");
          }
        },
      }));
      var hint = document.createElement("div");
      hint.className = "_eli3_settings_hint";
      hint.textContent = "Enable, reorder, and resize the daily widgets on the home dashboard (Word of the Day, Contract Trivia, Contract Joke).";
      wBox.appendChild(wRow);
      wBox.appendChild(hint);
    })();

    // Personalize ELI — opens the mascot customizer, the same editor you get
    // by clicking the ELI mascot in Ask ELI's welcome. eli_mascot_studio is
    // preload, so its tile handler is registered at boot.
    (function _wirePersonalizeSection() {
      var pBox = _section(panel, "Personalize ELI");
      var pRow = document.createElement("div");
      pRow.style.cssText = "display:flex;align-items:center;gap:10px;flex-wrap:wrap";
      pRow.appendChild(eliButton({
        label: "🎨 Personalize ELI",
        variant: "secondary",
        onclick: function () {
          // origin:"settings" → the studio's X / back returns to Settings → Interface.
          try { eli.dispatch("tile", "app_eli_mascot_studio", { origin: "settings" }); }
          catch (_e) {
            if (typeof showToast === "function") showToast("Mascot studio not available right now.", "warn");
          }
        },
      }));
      var pHint = document.createElement("div");
      pHint.className = "_eli3_settings_hint";
      pHint.textContent = "Customize what your ELI mascot looks like — the same editor you get by clicking ELI in Ask ELI.";
      pBox.appendChild(pRow);
      pBox.appendChild(pHint);
    })();

    // Reset View / Reset All (FROM v2 lines 5307 + 5310-5312).
    var resetBox = _section(panel, "Reset");
    var resetRow = document.createElement("div");
    resetRow.style.cssText = "display:flex;gap:8px;flex-wrap:wrap";
    resetRow.appendChild(eliButton({
      label: "↺ Reset View",
      variant: "secondary",
      onclick: eli.events.guard(function () {
        eli.events.safeAsync(eli.ui.confirm({
          title: "Reset view settings?",
          message: "Resets theme, light mode, sidebar, feed, and behavior toggles. API key and tools are not touched.",
        }), "settings.reset-view").then(function (ok) {
          if (!ok) return;
          var s = _readUserSettings();
          delete s.headerThemeIndex; delete s.lightMode;
          delete s.minimizeFeed;
          delete s.autoHideSidebar; delete s.autoExpandWindow;
          // Sweep legacy aiSpeechBubbles key from existing settings blobs
          // — the toggle was removed 2026-05-16 (never wired in v3).
          delete s.aiSpeechBubbles;
          _writeUserSettings(s);
          document.body.classList.remove("light-mode");
          if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
          showToast("View reset.", "ok");
        });
      }, "reset-view"),
    }));
    resetRow.appendChild(eliButton({
      label: "⚠️ Reset All",
      variant: "danger",
      onclick: eli.events.guard(function () {
        eli.events.safeAsync(eli.ui.confirm({
          title: "Reset everything?",
          message: "Clears local user settings, debug flag, and zoom level. API key, encrypted credentials, and installed tools are NOT touched. Reload after.",
        }), "settings.reset-all").then(function (ok) {
          if (!ok) return;
          try { eli.compat.lsRemove("eli_user_settings"); } catch (e) {}
          try { eli.compat.lsRemove("_eli3_zoom"); } catch (e) {}
          try { eli.compat.lsRemove("eli_rawBlocked"); } catch (e) {}
          try { eli.debug(false); } catch (e) {}
          document.body.classList.remove("light-mode");
          if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
          showToast("All view + debug settings reset.", "ok");
        });
      }, "reset-all"),
    }));
    resetBox.appendChild(resetRow);

    // Advanced group — skeleton templates + wrongness capture + verbose
    // logs, collapsed by default, last section on the card.
    _buildAdvancedSection(panel);
    _appendSaveChangesButton(panel);
  }

